// CRT Geom Lite - stack-safe minimal CRT look
#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;   // xy = size
    float4 SourceSize;   // xy = size
    float4 OriginalSize;
    uint   FrameCount;
    float  curvature;    // 0..1
    float  scanline;     // 0..1
    float  mask_strength;// 0..1
    float  vignette;     // 0..1
    float  gamma;        // 0.5..3
};

struct VSIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VSOut { float4 pos [[position]]; float2 uv; };

vertex VSOut main0(VSIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VSOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float2 barrel(float2 uv, float amt){
    float2 p = uv*2.0-1.0;
    float r2 = dot(p,p);
    float k = 0.25*amt;
    p *= 1.0 + k*r2;
    return clamp(p*0.5+0.5, 0.0, 1.0);
}

fragment float4 fragment_main(
    VSOut in [[stage_in]],
    texture2d<float> src [[texture(0)]],
    constant Uniforms &u [[buffer(0)]]
){
    constexpr sampler smp(mag_filter::linear, min_filter::linear, address::clamp_to_edge);

    // Curvature
    float2 uv = barrel(in.uv, clamp(u.curvature,0.0,1.0));

    // Sample
    float3 c = src.sample(smp, uv).rgb;

    // Scanlines (simple sine, resolution aware)
    float row = uv.y * u.OutputSize.y;
    float scan = 0.5 + 0.5*cos(6.28318*row);
    c *= mix(1.0, 0.8 + 0.2*scan, u.scanline);

    // Aperture mask (RGB triad)
    float colIdx = fract(uv.x * u.OutputSize.x / 1.0);
    float3 mask = float3(0.9,0.9,0.9);
    if (colIdx < 1.0/3.0) mask = float3(1.0,0.8,0.8);
    else if (colIdx < 2.0/3.0) mask = float3(0.8,1.0,0.8);
    else mask = float3(0.8,0.8,1.0);
    c = mix(c, c*mask, u.mask_strength*0.6);

    // Vignette
    float2 p = uv*2.0-1.0; float r = dot(p,p);
    c *= mix(1.0, smoothstep(1.0, 0.2, 1.0-r), u.vignette);

    // Gamma
    c = pow(max(c,0.0), float3(1.0/max(u.gamma,0.001)));

    return float4(saturate(c), 1.0);
}

